    />
    <div
      className="absolute top-0 right-0 w-4 h-4 bg-white border border-gray-400 cursor-ne-resize"
      onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'ne')}
      style={{ transform: 'translate(50%, -50%)' }}
    />
    <div
